import React from 'react';

import Nav from 'react-bootstrap/Nav';
import './NavMenu.css';

const NavMenu = () => {
  return (
    <div className='body-nav'>
      <Nav className="justify-content-end texto-nav" activeKey="/home">
        <Nav.Item>
          <Nav.Link href="/home" className="texto-nav-link">Home</Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="link-1" className="texto-nav-link"></Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="link-2" className="texto-nav-link">Link</Nav.Link>
        </Nav.Item>
        <Nav.Item>
          <Nav.Link eventKey="disabled"  className="texto-nav-link">Disabled</Nav.Link>
        </Nav.Item>
      </Nav>
    </div>
  );
}

export default NavMenu;
